# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(name, begin, stop):
    return Shift(name, "mon", Span(begin, stop))


class TimesheetTests(unittest.TestCase):
    def test_counts_and_hours(self):
        lines = timesheet_lines([
            make_shift("Brisa", 540, 750),
            make_shift("Brisa", 800, 1000)
        ])
        self.assertEqual(
            lines, ["Brisa: 2 shifts, 6.8 hours"]
        )

    def test_most_hours_first(self):
        lines = timesheet_lines([
            make_shift("Odell", 540, 600),
            make_shift("Quill", 540, 780),
            make_shift("Brisa", 540, 660)
        ])
        names = [line.split(":")[0] for line in lines]
        self.assertEqual(
            names, ["Quill", "Brisa", "Odell"]
        )

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            make_shift("Quill", 540, 600),
            make_shift("Odell", 540, 600)
        ])
        self.assertTrue(lines[0].startswith("Odell"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 540, 600)])
